import {PRODUCTS,ACCOUNT_EMAIL,ACCOUNT_PASSWORD,money,normalizeCart,calculate,filterProducts,validateCheckout,validateContact,isEmail,CONTACT_TOPICS,nextOrderId} from './model.js';
const KEY='goodfinds.v1';
const fresh=()=>({cart:[],coupon:'',user:null,orders:[]});
let state=fresh();
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'){state.cart=normalizeCart(saved.cart);state.coupon=saved.coupon==='SAVE10'?'SAVE10':'';state.user=saved.user?.email===ACCOUNT_EMAIL?{name:'Alex',email:ACCOUNT_EMAIL}:null;state.orders=Array.isArray(saved.orders)?saved.orders.filter(o=>o&&typeof o.id==='string'&&Array.isArray(o.items)&&Number.isInteger(o.total)).slice(0,100):[];}}catch{}
const filters={query:'',category:'All',sort:'featured',maxPrice:100,inStock:false};
let toastTimer,submitting=false,filterOpen=false;
const $=selector=>document.querySelector(selector);
const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',bag:'<path d="M5 7h14l-1 14H6L5 7Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',leaf:'<path d="M20 4C9 2 2 9 6 16s15 0 14-12ZM5 21 16 9"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',ticket:'<path d="M3 6h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4V6Zm12 0v3m0 3v1m0 3v2"/>'})[name]||''}</svg>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Progress lasts for this visit only.');}updateHeader();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function updateHeader(){const count=calculate(state.cart,state.coupon).count;$('.cart-count').textContent=count;$('#account-link').innerHTML=`${icon('user')}<span>${state.user?'Hi, Alex':'Sign in'}</span>`;$('#account-link').href=state.user?'#account':'#login';const route=location.hash.slice(1).split('/')[0]||'shop';document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function empty(title,text,action='Continue shopping',href='#shop'){return `<div class="empty">${icon('bag')}<h2>${title}</h2><p>${text}</p><a class="primary" href="${href}">${action} ${icon('arrow')}</a></div>`;}
function pageHead(title,text){return `<div class="page-head"><h1>${title}</h1><p>${text}</p></div>`;}
function productCard(p){const qty=state.cart.find(r=>r.id===p.id)?.qty||0;return `<article class="product ${!p.stock?'sold-out':''}" data-product-id="${p.id}" data-testid="product-${p.id}"><a class="product-image" href="#product/${p.id}" aria-label="View ${p.name}"><img src="./assets/${p.image}.jpg" alt="${p.name}" width="700" height="600" ${p.id==='p01'?'fetchpriority="high"':'loading="lazy"'}>${!p.stock?'<span class="stock-badge">Sold out</span>':p.id==='p01'?'<span class="stock-badge">Everyday favorite</span>':''}</a><p class="product-category">${p.category} / ${p.color}</p><h2 class="product-title"><a href="#product/${p.id}">${p.name}</a></h2><div class="product-bottom"><span class="price">${money(p.price)}</span><button class="add-button" data-action="add" data-id="${p.id}" data-testid="add-${p.id}" aria-label="Add ${p.name} to cart" ${!p.stock||qty>=p.stock?'disabled':''}>${p.stock?`${icon('plus')} ${qty>=p.stock?'Limit reached':'Add to cart'}`:'Unavailable'}</button></div></article>`;}
function shop(){return `<section class="intro"><div><h1>Everyday, considered.</h1><p>Good finds for your desk, your day, and everything in between.</p></div><div class="intro-aside">${icon('leaf')}<span>A thoughtfully small collection.<br>A whole lot to explore.</span></div></section><button class="filter-mobile-toggle" data-action="toggle-filters" aria-expanded="${filterOpen}" aria-controls="filters">${icon('filter')} Filters</button><div class="shop-layout"><aside id="filters" class="filters ${filterOpen?'open':''}" aria-label="Product filters"><div class="filter-title"><strong>Filters</strong><button class="text-button" data-action="clear-filters" data-testid="clear-filters">Clear all</button></div><fieldset><legend>Category</legend>${['All','Everyday','Desk','Audio'].map(c=>`<label class="category"><input type="radio" name="category" value="${c}" ${filters.category===c?'checked':''}><span>${c==='All'?'All products':c}</span><span>${c==='All'?8:PRODUCTS.filter(p=>p.category===c).length}</span></label>`).join('')}</fieldset><label class="filter-label" for="max-price">Price range</label><div class="price-label"><span>$0</span><span id="price-output">Up to $${filters.maxPrice}</span></div><input id="max-price" type="range" min="0" max="100" step="1" value="${filters.maxPrice}" data-testid="price-range"><div class="filter-divider"></div><label class="check-label"><input id="in-stock" type="checkbox" ${filters.inStock?'checked':''} data-testid="in-stock"> In-stock items only</label><div class="offer">${icon('ticket')}<h3>A little extra good.</h3><p>Take 10% off your order with code <strong>SAVE10</strong>.</p></div></aside><section aria-label="Product catalog"><div class="toolbar"><div class="search-wrap">${icon('search')}<label class="sr-only" for="search">Search products</label><input type="search" id="search" value="${escape(filters.query)}" placeholder="Search the collection…" data-testid="product-search"></div><label class="sr-only" for="sort">Sort products</label><select id="sort" data-testid="sort-products"><option value="featured">Sort: Featured</option><option value="price-asc">Price: Low to high</option><option value="price-desc">Price: High to low</option><option value="name">Name: A to Z</option></select></div><div class="results-meta"><span id="results-count" role="status"></span><span>Prices in USD</span></div><div class="grid" id="product-grid"></div></section></div>`;}
function updateCatalog(){if(!$('#product-grid'))return;const rows=filterProducts(filters);$('#results-count').innerHTML=`Showing <strong>${rows.length}</strong> of 8 products`;$('#product-grid').innerHTML=rows.length?rows.map(productCard).join(''):`<div style="grid-column:1/-1">${empty('No finds this time.','Try another search or clear your filters to see the full collection.','Clear filters','#clear-filters')}</div>`;$('#sort').value=filters.sort;}
function summary(action=true){const t=calculate(state.cart,state.coupon);return `<aside class="summary" aria-label="Order summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal (${t.count} ${t.count===1?'item':'items'})</span><span data-testid="subtotal">${money(t.subtotal)}</span></div>${t.discount?`<div class="summary-line"><span>Discount · SAVE10</span><span data-testid="discount">−${money(t.discount)}</span></div>`:''}<div class="summary-line"><span>Shipping</span><span data-testid="shipping">${t.shipping?money(t.shipping):'Free'}</span></div><div class="summary-line"><span>Tax (8%)</span><span data-testid="tax">${money(t.tax)}</span></div><div class="summary-line total"><span>Total</span><span data-testid="total">${money(t.total)}</span></div>${action?`<a class="primary full" href="#checkout" data-testid="checkout-link">Proceed to checkout ${icon('arrow')}</a>`:''}<p>Shipping is $6, or free on orders of $100+ after discounts. Tax applies to discounted products only.</p>${action?`<form class="coupon" id="coupon-form" novalidate><label for="coupon-code">Have a discount code?</label><div class="coupon-row"><input id="coupon-code" name="coupon" placeholder="Enter code" value="${escape(state.coupon)}" data-testid="coupon-input"><button class="secondary" type="submit" data-testid="apply-coupon">Apply</button></div><div id="coupon-status" class="coupon-status" role="status">${state.coupon?`<span class="success">SAVE10 applied. <button type="button" class="text-button" data-action="remove-coupon">Remove</button></span>`:''}</div></form>`:''}</aside>`;}
function cart(){return pageHead('Your cart','A few good things, ready when you are.')+(state.cart.length?`<div class="content-split"><div>${state.cart.map(row=>{const p=PRODUCTS.find(p=>p.id===row.id);return `<article class="cart-row" data-testid="cart-item-${p.id}"><a href="#product/${p.id}"><img src="./assets/${p.image}.jpg" alt="${p.name}" width="96" height="100"></a><div class="cart-item-info"><h3><a href="#product/${p.id}">${p.name}</a></h3><p>${p.color} · ${money(p.price)} each</p><div class="qty" aria-label="Quantity for ${p.name}"><button data-action="decrease" data-id="${p.id}" aria-label="Decrease ${p.name} quantity" ${row.qty<=1?'disabled':''}>−</button><span data-testid="quantity-${p.id}">${row.qty}</span><button data-action="increase" data-id="${p.id}" aria-label="Increase ${p.name} quantity" ${row.qty>=p.stock?'disabled':''}>+</button></div><button class="text-button remove" data-action="remove" data-id="${p.id}" aria-label="Remove ${p.name}">Remove</button></div><span class="price">${money(p.price*row.qty)}</span></article>`;}).join('')}<a class="back" href="#shop">${icon('back')} Continue shopping</a></div>${summary()}</div>`:empty('Your cart has room for something good.','Explore the collection and add a few everyday favorites.'));}
const field=(id,label,type='text',wide=false)=>`<div class="field ${wide?'wide':''}"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" autocomplete="${({name:'name',email:'email',address:'street-address',city:'address-level2',postal:'postal-code'})[id]}" aria-describedby="error-${id}" data-testid="checkout-${id}" ${id==='email'&&state.user?`value="${ACCOUNT_EMAIL}"`:''}><p class="error" id="error-${id}" aria-live="polite"></p></div>`;
function checkout(){if(!state.cart.length)return pageHead('Checkout','Your cart is currently empty.')+empty('Let’s find something first.','Add a product before starting checkout.');return pageHead('A few details, then you’re done.','Guest checkout · No account needed')+`<div class="content-split"><form id="checkout-form" novalidate><section class="form-section"><h2>Delivery details</h2><div class="fields">${field('name','Full name')}${field('email','Email address','email')}${field('address','Street address','text',true)}${field('city','City')}${field('postal','Postal code')}<div class="field wide"><label for="country">Country</label><select id="country" name="country" aria-describedby="error-country" data-testid="checkout-country"><option value="">Select a country</option><option value="US">United States</option><option value="GB">United Kingdom</option><option value="CA">Canada</option><option value="TW">Taiwan</option><option value="AU">Australia</option></select><p class="error" id="error-country" aria-live="polite"></p></div></div></section><section class="form-section"><h2>Payment</h2><div class="payment-note">${icon('lock')}<div><h3>Pay on delivery.</h3><p>No card needed now. You’ll pay when your order arrives.</p></div></div><div class="agreement"><label class="check-label"><input type="checkbox" id="agree" name="agree" aria-describedby="error-agree" data-testid="checkout-agree"> I agree to the <a href="#terms" target="_blank">terms of sale</a>.</label><p class="error" id="error-agree" aria-live="polite"></p></div><button class="primary full" type="submit" data-testid="place-order">Place order ·${money(calculate(state.cart,state.coupon).total)} ${icon('arrow')}</button><p class="error" id="checkout-error" role="alert"></p></section></form>${summary(false)}</div>`;}
function login(){return `<div class="login-shell"><a class="back" href="#shop">${icon('back')} Back to the shop</a><h1>A familiar face.</h1><p>Sign in to see your orders and check out faster.</p><form id="login-form" novalidate><div class="field"><label for="login-email">Email address</label><input type="email" id="login-email" name="email" autocomplete="username" data-testid="login-email" aria-describedby="login-error"></div><div class="field"><label for="login-password">Password</label><input type="password" id="login-password" name="password" autocomplete="current-password" data-testid="login-password" aria-describedby="login-error"></div><p id="login-error" class="error" role="alert"></p><button class="primary full" type="submit" data-testid="sign-in">Sign in ${icon('arrow')}</button></form><p class="subtle" style="margin-top:18px">Shopping and checkout also work without signing in.</p></div>`;}
function account(){return pageHead('Hello, Alex.','Welcome back.')+`<div class="guide-callout" style="max-width:500px"><h2>Your profile</h2><p>${ACCOUNT_EMAIL}</p><p>Track everything you’ve ordered under My orders.</p><div class="button-row"><a class="primary" href="#orders">View my orders</a><button class="secondary" data-action="logout" data-testid="sign-out">Sign out</button></div></div>`;}
function orderMarkup(o){return `<article class="order" data-testid="order-${escape(o.id)}"><div class="order-heading"><div><h3>${escape(o.id)}</h3><p>${escape(new Date(o.date).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}))} · ${escape(o.customer?.email)}</p></div><span class="order-status">${icon('check')} Confirmed</span></div><div class="order-items">${o.items.map(r=>`${escape(r.name)} × ${escape(r.qty)}`).join(' · ')}</div><div class="summary-line"><span>Deliver to ${escape(o.customer?.name)}, ${escape(o.customer?.address)}, ${escape(o.customer?.city)}, ${escape(o.customer?.postal)}, ${escape(o.customer?.country)}</span></div><div class="order-total">${money(o.total)}</div></article>`;}
function orders(){return pageHead('Your good finds, all in one place.','Your recent orders.')+(state.orders.length?state.orders.map(orderMarkup).join(''):empty('No orders just yet.','Once you place an order, it will appear here.'));}
function confirmation(id){const o=state.orders.find(o=>o.id===id);if(!o)return pageHead('Order not found','We couldn’t find this order.')+empty('A fresh start.','Your current order history is available below.','View orders','#orders');return `<div class="page-head"></div><section class="confirmation" data-testid="order-confirmation">${icon('check')}<h1>That’s a good order.</h1><p>Your order <strong data-testid="confirmed-order-id">${escape(o.id)}</strong> is confirmed. Thanks for shopping with us.</p><div class="button-row" style="justify-content:center"><a class="primary" href="#orders">View my orders</a><a class="secondary" href="#shop">Keep exploring</a></div></section>${orderMarkup(o)}`;}
function detail(id){const p=PRODUCTS.find(p=>p.id===id);if(!p)return pageHead('Product not found','This product isn’t in our collection.')+empty('Let’s try the collection.','Browse everything we have in stock.');const qty=state.cart.find(r=>r.id===id)?.qty||0;return `<div class="page-head"><a class="back" href="#shop">${icon('back')} Back to the collection</a><div class="detail"><img src="./assets/${p.image}.jpg" alt="${p.name}"><div><p class="subtle">${p.category} / ${p.color}</p><h1>${p.name}</h1><p class="detail-description">${p.description}</p><div class="price">${money(p.price)}</div><div class="detail-meta"><span>${p.stock?`${p.stock} available per order`:'Currently sold out'}</span><span>Product ID: ${p.id}</span></div><button class="primary" data-action="add" data-id="${p.id}" data-testid="add-${p.id}" ${!p.stock||qty>=p.stock?'disabled':''}>${p.stock?`${icon('plus')} ${qty>=p.stock?'Stock limit reached':'Add to cart'}`:'Sold out'}</button></div></div></div>`;}
const section=(title,body)=>`<section><h2>${title}</h2>${body}</section>`;
function about(){return pageHead('Fewer, better things.','Goodfinds is a small shop for the everyday essentials we actually use.')+`<div class="info">${section('Our story','<p>Goodfinds started with a simple idea: the things you use every day deserve a little more thought. A bag that survives the commute, a mug that feels right in your hand, a notebook that fits in your pocket.</p><p>We keep the collection small on purpose. If we wouldn’t recommend something to a friend, it doesn’t make the cut.</p>')}${section('How we work','<ul><li>A short, carefully chosen collection that changes slowly.</li><li>Flat $6 shipping, free on orders of $100 or more.</li><li>Pay on delivery, so there’s no card needed at checkout.</li><li>30-day returns on unused items.</li></ul>')}${section('Say hello','<p>Questions, ideas, or a product you think we should carry? <a href="#contact">Get in touch</a>. We reply within 1–2 business days.</p>')}</div>`;}
function shipping(){return pageHead('Shipping &amp; returns','Getting your order to you, and sending it back if it isn’t right.')+`<div class="info">${section('Where we ship','<p>We deliver to the United States, the United Kingdom, Canada, Taiwan, and Australia.</p>')}${section('Shipping costs','<p>Shipping is a flat $6 per order. Orders of $100 or more after discounts ship free. Orders usually leave our warehouse within 2 business days.</p>')}${section('Payment','<p>We use pay on delivery: there’s no card needed at checkout, and you pay when your order arrives.</p>')}${section('Tax','<p>An 8% sales tax applies to merchandise after any discount. Shipping isn’t taxed.</p>')}${section('Returns','<p>Changed your mind? Return unused items in their original condition within 30 days of delivery for a full refund. <a href="#contact">Contact us</a> with your order number (it starts with GF-) to start a return.</p>')}</div>`;}
const FAQS=[
['How much is shipping?','A flat $6 per order, and free when your order is $100 or more after discounts.'],
['How do I pay?','You pay on delivery. No card details are needed at checkout.'],
['Do I need an account to order?','No. You can check out as a guest. If you’re signed in, we fill in your email at checkout.'],
['Where can I see my orders?','Under My orders in the main menu. Each order number starts with GF-.'],
['Is there a limit on how many I can buy?','Some items have a per-order limit, shown on the product page. Once you reach it, you can’t add more of that item.'],
['Do you have a discount code?','Enter SAVE10 in your cart for 10% off merchandise.'],
['What does “Sold out” mean?','The item isn’t available right now and can’t be added to your cart. Check back soon.'],
['Which countries do you ship to?','The United States, the United Kingdom, Canada, Taiwan, and Australia.'],
['How do I return something?','Unused items can be returned within 30 days of delivery. See <a href="#shipping">Shipping &amp; returns</a> for details.']
];
function faq(){return pageHead('Frequently asked questions','Quick answers about orders, shipping, and returns.')+`<div class="faq info">${FAQS.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}<p class="subtle" style="margin-top:24px">Still stuck? <a href="#contact">Contact us</a> and we’ll help.</p></div>`;}
const contactField=(id,label,type)=>`<div class="field"><label for="contact-${id}">${label}</label><input id="contact-${id}" name="${id}" type="${type}" autocomplete="${id}" aria-describedby="error-contact-${id}" data-testid="contact-${id}" ${id==='email'&&state.user?`value="${ACCOUNT_EMAIL}"`:''}><p class="error" id="error-contact-${id}" aria-live="polite"></p></div>`;
function contact(){return pageHead('Get in touch.','Questions about an order, a product, or anything else. We reply within 1–2 business days.')+`<div class="content-split"><form id="contact-form" novalidate><div class="fields">${contactField('name','Your name','text')}${contactField('email','Email address','email')}<div class="field wide"><label for="contact-topic">What’s it about?</label><select id="contact-topic" name="topic" aria-describedby="error-contact-topic" data-testid="contact-topic"><option value="">Choose a topic</option>${Object.entries(CONTACT_TOPICS).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select><p class="error" id="error-contact-topic" aria-live="polite"></p></div><div class="field wide"><label for="contact-message">Message</label><textarea id="contact-message" name="message" aria-describedby="error-contact-message" data-testid="contact-message"></textarea><p class="error" id="error-contact-message" aria-live="polite"></p></div></div><button class="primary" type="submit" data-testid="contact-submit" style="margin-top:22px">Send message ${icon('arrow')}</button></form><aside class="guide-callout"><h2>Other ways to reach us</h2><p>Email: support@goodfinds.example<br>Hours: Monday–Friday, 9am–5pm</p><p>Have an order number? Include it so we can help faster.</p><p><a href="#faq">Browse the FAQ</a></p></aside></div>`;}
function terms(){return pageHead('Terms of sale','Last updated October 2026.')+`<div class="info">${section('Orders','<p>Placing an order is an offer to buy. Once it’s confirmed, you’ll see an order number starting with GF-. We may cancel an order if an item turns out to be unavailable.</p>')}${section('Prices and tax','<p>Prices are in US dollars. An 8% sales tax is added to merchandise after discounts at checkout.</p>')}${section('Payment','<p>Payment is collected on delivery.</p>')}${section('Discount codes','<p>One code per order. Codes apply to merchandise only, not to shipping or tax.</p>')}${section('Quantity limits','<p>Some products have a per-order quantity limit, shown on the product page.</p>')}${section('Shipping and returns','<p>See <a href="#shipping">Shipping &amp; returns</a> for delivery costs, countries, and our 30-day return policy.</p>')}</div>`;}
function privacy(){return pageHead('Privacy policy','Last updated October 2026.')+`<div class="info">${section('What we collect','<p>When you check out, we ask for your name, email address, and delivery address. If you contact us or join our email list, we keep the details you send.</p>')}${section('How we use it','<p>To deliver your order, reply to your messages, and, if you subscribe, send occasional emails about new arrivals and offers. We don’t sell your information.</p>')}${section('Storage in your browser','<p>We keep your cart, sign-in, and order history in your browser so they’re still there when you come back.</p>')}${section('Your choices','<p>You can unsubscribe from emails at any time, or ask us to delete your details through our <a href="#contact">contact page</a>.</p>')}</div>`;}
function render(focus=false){let [route,id]=location.hash.slice(1).split('/');route=route||'shop';if(route==='clear-filters'){clearFilters();location.hash='shop';return;}const views={shop,cart,checkout,login,account:()=>state.user?account():login(),orders,about,shipping,faq,contact,terms,privacy,product:()=>detail(id),confirmation:()=>confirmation(id)};$('#main').innerHTML=(views[route]||(()=>pageHead('This page wandered off.','Use the navigation to get back to the collection.')+empty('Back to good things.','The shop is always a good place to start.')))();if(route==='shop')updateCatalog();updateHeader();document.title=`${({shop:'Shop',cart:'Your cart',checkout:'Checkout',orders:'My orders',about:'About us',shipping:'Shipping & returns',faq:'FAQ',contact:'Contact us',terms:'Terms of sale',privacy:'Privacy policy',login:'Sign in',account:'My account',product:PRODUCTS.find(p=>p.id===id)?.name,confirmation:'Order confirmed'})[route]||'Page'} · Goodfinds`;if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}}
function clearFilters(){Object.assign(filters,{query:'',category:'All',sort:'featured',maxPrice:100,inStock:false});}
function changeQty(id,change){const row=state.cart.find(r=>r.id===id);const p=PRODUCTS.find(p=>p.id===id);if(!p||!row||row.qty+change<1||row.qty+change>p.stock)return;row.qty+=change;persist();render();}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;if(action==='add'){const p=PRODUCTS.find(p=>p.id===id);const row=state.cart.find(r=>r.id===id);if(!p?.stock||row?.qty>=p.stock)return;if(row)row.qty++;else state.cart.push({id,qty:1});persist();if($('#product-grid'))updateCatalog();else render();toast(`${p.name} added to your cart.`);}if(action==='increase')changeQty(id,1);if(action==='decrease')changeQty(id,-1);if(action==='remove'){state.cart=state.cart.filter(r=>r.id!==id);persist();render();toast('Item removed from your cart.');}if(action==='clear-filters'){clearFilters();render();}if(action==='toggle-filters'){filterOpen=!filterOpen;$('#filters').classList.toggle('open',filterOpen);button.setAttribute('aria-expanded',String(filterOpen));}if(action==='remove-coupon'){state.coupon='';persist();render();}if(action==='logout'){state.user=null;persist();location.hash='shop';toast('You’re signed out. Your cart is saved.');}});
document.addEventListener('input',event=>{if(event.target.id==='search'){filters.query=event.target.value;updateCatalog();}if(event.target.id==='max-price'){filters.maxPrice=Number(event.target.value);$('#price-output').textContent=`Up to $${filters.maxPrice}`;updateCatalog();}});
document.addEventListener('change',event=>{if(event.target.name==='category')filters.category=event.target.value;if(event.target.id==='sort')filters.sort=event.target.value;if(event.target.id==='in-stock')filters.inStock=event.target.checked;if(event.target.closest('#filters')||event.target.id==='sort')updateCatalog();});
document.addEventListener('submit',async event=>{const form=event.target;event.preventDefault();if(form.id==='newsletter-form'){const input=$('#newsletter-email');const ok=isEmail(input.value);input.setAttribute('aria-invalid',String(!ok));$('#newsletter-status').innerHTML=ok?'<span class="success">You’re subscribed. Watch your inbox for new arrivals.</span>':'<span class="error">Enter a valid email address.</span>';if(ok)input.value='';}if(form.id==='contact-form'){const data=Object.fromEntries(new FormData(form));const errors=validateContact(data);for(const name of ['name','email','topic','message']){$(`#error-contact-${name}`).textContent=errors[name]||'';$(`#contact-${name}`).setAttribute('aria-invalid',String(!!errors[name]));}if(Object.keys(errors).length){$(`#contact-${Object.keys(errors)[0]}`).focus();return;}form.outerHTML=`<section class="guide-callout contact-sent" data-testid="contact-success" tabindex="-1"><h2>Thanks, ${escape(data.name.trim())}. Your message is on its way.</h2><p>We’ll reply to ${escape(data.email.trim())} within 1–2 business days.</p><a class="primary" href="#shop">Back to the shop ${icon('arrow')}</a></section>`;$('[data-testid=contact-success]').focus();}if(form.id==='coupon-form'){const value=$('#coupon-code').value.trim().toUpperCase();if(value!=='SAVE10'){$('#coupon-status').innerHTML='<span class="error">That code isn’t valid.</span>';$('#coupon-code').setAttribute('aria-invalid','true');return;}state.coupon='SAVE10';persist();render();toast('SAVE10 applied. A little extra good.');}if(form.id==='login-form'){const email=$('#login-email').value.trim().toLowerCase(),password=$('#login-password').value;if(email!==ACCOUNT_EMAIL||password!==ACCOUNT_PASSWORD){$('#login-error').textContent='Email or password is incorrect.';$('#login-email').setAttribute('aria-invalid','true');$('#login-password').setAttribute('aria-invalid','true');$('#login-email').focus();return;}state.user={name:'Alex',email:ACCOUNT_EMAIL};persist();location.hash='account';toast('Welcome back, Alex.');}if(form.id==='checkout-form'){if(submitting||!state.cart.length)return;const data=Object.fromEntries(new FormData(form));data.agree=$('#agree').checked;const errors=validateCheckout(data);for(const name of ['name','email','address','city','postal','country','agree']){$(`#error-${name}`).textContent=errors[name]||'';$(`#${name}`).setAttribute('aria-invalid',String(!!errors[name]));}if(Object.keys(errors).length){$(`#${Object.keys(errors)[0]}`).focus();return;}submitting=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Placing your order…';try{const totals=calculate(state.cart,state.coupon);const order={id:nextOrderId(state.orders),date:new Date().toISOString(),customer:Object.fromEntries(['name','email','address','city','postal','country'].map(k=>[k,String(data[k]).trim()])),items:state.cart.map(r=>({...r,name:PRODUCTS.find(p=>p.id===r.id).name,price:PRODUCTS.find(p=>p.id===r.id).price})),coupon:state.coupon,...totals};state.orders.unshift(order);state.cart=[];state.coupon='';persist();location.hash=`confirmation/${order.id}`;}catch{if(form.isConnected){$('#checkout-error').textContent='The order could not be created. Please try again.';submit.disabled=false;submit.textContent='Place order';}}finally{submitting=false;}}});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
document.addEventListener('click',event=>{const control=event.target.closest('[data-action]');if(!control||!['add','increase','decrease'].includes(control.dataset.action))return;const {action,id}=control.dataset;const updated=document.querySelector(`[data-action="${action}"][data-id="${id}"]:not(:disabled)`);const fallback=document.querySelector(`.product[data-product-id="${id}"] .product-title a, [data-testid="cart-item-${id}"] .qty button:not(:disabled), .detail + a`);(updated||fallback||$('#main')).focus({preventScroll:true});});
window.addEventListener('hashchange',()=>render(true));
window.addEventListener('storage',event=>{if(event.key===KEY)location.reload();});
render();
